content:
:root {
  --bg-color: #f0f2f5;
  --app-bg: #ffffff;
  --text-primary: #333333;
  --text-title: #1a1a1a;
  --text-info: #65676b;
  --shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  --border-color: #e4e6eb;
  --control-bg: #f8f9fa;
  --btn-bg: #e4e6eb;
  --btn-hover: #d8dadf;
  --btn-text: #050505;
  --btn-primary-bg: #006400;
  --btn-primary-hover: #005000;
  --canvas-bg: #fafafa;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-primary);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 800px;
  background: var(--app-bg);
  border-radius: 12px;
  box-shadow: var(--shadow);
  overflow: hidden;
  padding: 20px;
  margin: 10px;
}

.header {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-bottom: 16px;
  width: 100%;
  text-align: center;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-title);
  margin-bottom: 8px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  align-items: center;
  margin-bottom: 16px;
  width: 100%;
  background: var(--control-bg);
  padding: 12px;
  border-radius: 8px;
}

.controls label {
  font-size: 0.9rem;
  font-weight: 500;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.controls input[type="range"] {
  cursor: pointer;
}

.btn {
  background-color: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:hover {
  background-color: var(--btn-hover);
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--btn-primary-bg);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--btn-primary-hover);
}

.canvas-container {
  position: relative;
  width: 100%;
  max-width: 720px;
  height: 400px;
  border: 2px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  background-color: var(--canvas-bg);
  cursor: crosshair;
}

.canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.info {
  margin-top: 12px;
  font-size: 0.85rem;
  color: var(--text-info);
  text-align: center;
}

@media (max-width: 600px) {
  .app-container {
    padding: 12px;
    margin: 8px;
  }

  .controls {
    flex-direction: column;
    align-items: stretch;
    padding: 10px;
  }

  .canvas-container {
    height: 300px;
  }
}

/**
 * ボールの物理状態を表すインターフェース
 */
export interface Ball {
  /** 一意識別子 */
  id: number;
  /** X座標 (キャンバス内のピクセル位置) */
  x: number;
  /** Y座標 (キャンバス内のピクセル位置) */
  y: number;
  /** X方向の速度 */
  vx: number;
  /** Y方向の速度 */
  vy: number;
  /** ボールの半径 (ピクセル) */
  radius: number;
  /** ボールの色 (CSSカラーコード) */
  color: string;
  /** ボールの質量 (将来的な衝突計算や物理演算の拡張用) */
  mass?: number;
}

/**
 * シミュレーション全体の設定を表すインターフェース
 */
export interface SimulationConfig {
  /** 重力加速度 */
  gravity: number;
  /** 反発係数 (0.0 から 1.0 の範囲) */
  restitution: number;
}

import { useRef, useEffect } from 'react';
import { Ball, SimulationConfig } from '../types';

interface PhysicsCanvasProps {
  balls: Ball[];
  config: SimulationConfig;
  isPaused?: boolean;
  onAddBall: (x: number, y: number) => void;
}

export default function PhysicsCanvas({
  balls,
  config,
  isPaused = false,
  onAddBall,
}: PhysicsCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[]>(balls);
  const isPausedRef = useRef<boolean>(isPaused);

  // 仮想キャンバスサイズ
  const WIDTH = 720;
  const HEIGHT = 400;

  // 親からのballs変更をrefに同期（リセットやクリア、追加時など）
  useEffect(() => {
    ballsRef.current = balls;
  }, [balls]);

  // 親からのisPaused変更をrefに同期
  useEffect(() => {
    isPausedRef.current = isPaused;
  }, [isPaused]);

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const scaleX = WIDTH / rect.width;
    const scaleY = HEIGHT / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    onAddBall(x, y);
  };

  // Canvasの初期設定（Retinaディスプレイ対応）
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = WIDTH * dpr;
    canvas.height = HEIGHT * dpr;
    ctx.scale(dpr, dpr);
  }, []);

  useEffect(() => {
    let animationFrameId: number;

    const render = () => {
      const canvas = canvasRef.current;
      if (canvas) {
        const ctx = canvas.getContext('2d');
        if (ctx) {
          const currentBalls = ballsRef.current;

          if (!isPausedRef.current) {
            // 物理演算の更新（refを直接更新してパフォーマンスを改善）
            for (let i = 0; i < currentBalls.length; i++) {
              const ball = currentBalls[i];

              // 重力の適用
              ball.vy += config.gravity;

              // 位置の更新
              ball.x += ball.vx;
              ball.y += ball.vy;

              // 床との衝突 (Bottom)
              if (ball.y + ball.radius > HEIGHT) {
                ball.y = HEIGHT - ball.radius;
                ball.vy = -ball.vy * config.restitution;
                ball.vx *= 0.98; // 摩擦
              }

              // 天井との衝突 (Top)
              if (ball.y - ball.radius < 0) {
                ball.y = ball.radius;
                ball.vy = -ball.vy * config.restitution;
              }

              // 右壁との衝突 (Right)
              if (ball.x + ball.radius > WIDTH) {
                ball.x = WIDTH - ball.radius;
                ball.vx = -ball.vx * config.restitution;
              }

              // 左壁との衝突 (Left)
              if (ball.x - ball.radius < 0) {
                ball.x = ball.radius;
                ball.vx = -ball.vx * config.restitution;
              }

              // 速度が極小の場合は0にする
              if (Math.abs(ball.vx) < 0.05) ball.vx = 0;
              if (Math.abs(ball.vy) < 0.05 && Math.abs(ball.y - (HEIGHT - ball.radius)) < 1) ball.vy = 0;
            }

            // ボール同士の衝突判定（弾性衝突）
            for (let i = 0; i < currentBalls.length; i++) {
              for (let j = i + 1; j < currentBalls.length; j++) {
                const b1 = currentBalls[i];
                const b2 = currentBalls[j];
                const dx = b2.x - b1.x;
                const dy = b2.y - b1.y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                const minDist = b1.radius + b2.radius;

                if (dist < minDist && dist > 0) {
                  const overlap = minDist - dist;
                  const nx = dx / dist;
                  const ny = dy / dist;

                  const m1 = b1.radius;
                  const m2 = b2.radius;

                  // 位置の補正（めり込み解消）
                  b1.x -= nx * overlap * (m2 / (m1 + m2));
                  b1.y -= ny * overlap * (m2 / (m1 + m2));
                  b2.x += nx * overlap * (m1 / (m1 + m2));
                  b2.y += ny * overlap * (m1 / (m1 + m2));

                  // 弾性衝突の計算（運動量保存則）
                  const kx = b1.vx - b2.vx;
                  const ky = b1.vy - b2.vy;
                  const p = (2 * (nx * kx + ny * ky)) / (m1 + m2);

                  b1.vx -= p * m2 * nx * config.restitution;
                  b1.vy -= p * m2 * ny * config.restitution;
                  b2.vx += p * m1 * nx * config.restitution;
                  b2.vy += p * m1 * ny * config.restitution;
                }
              }
            }
          }

          // 描画クリア
          ctx.clearRect(0, 0, WIDTH, HEIGHT);

          // ボールの描画
          currentBalls.forEach((ball) => {
            ctx.beginPath();
            ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
            ctx.fillStyle = ball.color;
            ctx.fill();
            ctx.lineWidth = 2;
            ctx.strokeStyle = '#00000022';
            ctx.stroke();
            ctx.closePath();
          });
        }
      }

      animationFrameId = requestAnimationFrame(render);
    };

    animationFrameId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [config]);

  return (
    <div className="canvas-container">
      <canvas
        ref={canvasRef}
        width={WIDTH}
        height={HEIGHT}
        className="canvas"
        onClick={handleCanvasClick}
      />
    </div>
  );
}

import { useState, useRef } from 'react';
import PhysicsCanvas from './components/PhysicsCanvas';
import { Ball, SimulationConfig } from './types';
import './index.css';

const INITIAL_BALLS: Ball[] = [
  { id: 1, x: 150, y: 100, vx: 3, vy: 0, radius: 20, color: '#ff5722' },
  { id: 2, x: 360, y: 150, vx: -2, vy: 1, radius: 25, color: '#4caf50' },
  { id: 3, x: 550, y: 80, vx: 1, vy: -2, radius: 18, color: '#2196f3' },
];

const COLORS = ['#ff5722', '#4caf50', '#2196f3', '#e91e63', '#ffeb3b', '#9c27b0'];

export default function App() {
  const [balls, setBalls] = useState<Ball[]>(INITIAL_BALLS);
  const [config, setConfig] = useState<SimulationConfig>({
    gravity: 0.4,
    restitution: 0.7,
  });
  const [isPaused, setIsPaused] = useState<boolean>(false);
  const nextIdRef = useRef<number>(100);

  const handleAddBallAt = (x: number, y: number) => {
    const newRadius = Math.floor(Math.random() * 12) + 15;

    const newBall: Ball = {
      id: nextIdRef.current++,
      x,
      y,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 4,
      radius: newRadius,
      color: COLORS[Math.floor(Math.random() * COLORS.length)],
    };
    setBalls((prev) => [...prev, newBall]);
  };

  const handleAddRandomBall = () => {
    handleAddBallAt(360 + (Math.random() - 0.5) * 200, 100);
  };

  const handleReset = () => {
    setBalls(INITIAL_BALLS);
    setConfig({ gravity: 0.4, restitution: 0.7 });
    setIsPaused(false);
  };

  const handleClear = () => {
    setBalls([]);
  };

  const handleTogglePause = () => {
    setIsPaused((prev) => !prev);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">物理バウンシングシミュレーション</h1>
      </header>

      <div className="controls">
        <label>
          重力: {config.gravity.toFixed(1)}
          <input
            type="range"
            min="0"
            max="1"
            step="0.1"
            value={config.gravity}
            onChange={(e) =>
              setConfig({ ...config, gravity: parseFloat(e.target.value) })
            }
          />
        </label>

        <label>
          反発係数: {config.restitution.toFixed(1)}
          <input
            type="range"
            min="0.1"
            max="1"
            step="0.1"
            value={config.restitution}
            onChange={(e) =>
              setConfig({ ...config, restitution: parseFloat(e.target.value) })
            }
          />
        </label>

        <button className="btn btn-primary" onClick={handleAddRandomBall}>
          ボール追加
        </button>
        <button className="btn" onClick={handleTogglePause}>
          {isPaused ? '再開' : '一時停止'}
        </button>
        <button className="btn" onClick={handleClear}>
          全消去
        </button>
        <button className="btn" onClick={handleReset}>
          リセット
        </button>
      </div>

      <PhysicsCanvas
        balls={balls}
        config={config}
        isPaused={isPaused}
        onAddBall={handleAddBallAt}
      />

      <div className="info">
        キャンバスをクリックするか「ボール追加」ボタンでボールを投入できます。
      </div>
    </div>
  );
}
